mod solution;

fn main() {
    let cases = [
    (r#"[5,2,4,6,1,3]"#, r#"1,2,3,4,5,6"#),
    (r#"[3,1]"#, r#"1,3"#),
    (r#"
[3,1]
"#, r#"1,3"#),
    (r#"  
[5,2,4,6,1,3]
  "#, r#"1,2,3,4,5,6"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS insertion-sort");
}
